+        if (warning != null) {
+            return warning;
+        }
+
+        warning = recursiveCheckDoNotMockAnnotationForType(type.getSuperclass());
+        if (warning != null) {
+            return warning;
+        }
+
+        for (Class<?> aClass : type.getInterfaces()) {
+            warning = recursiveCheckDoNotMockAnnotationForType(aClass);
+            if (warning != null) {
+                return warning;
+            }
+        }
