+        assertThat(mock.getTestEnum()).isEqualTo(TestEnum.B);
+    }
+
+    @Test
+    public void deep_stub_can_mock_enum_class_Issue_2984() {
+        final var mock = mock(TestEnum.class, RETURNS_DEEP_STUBS);
