+import static org.mockito.Mockito.when;
+
+import org.junit.Test;
+
+public class DeepStubReturnsEnumJava11Test {
+    private static final String MOCK_VALUE = "Mock";
+
+    @Test
+    public void deep_stub_can_mock_enum_getter_Issue_2984() {
