+        return "eclipse-temurin:11-jre";
+      }
+      if (processor.getJavaVersion() <= 17) {
+        return "eclipse-temurin:17-jre";
+      }
+      return "eclipse-temurin:21-jre";
+    }
+
+    private JarFiles() {}
+}
